from __future__ import annotations

import ast
import base64
import os
import re
import shutil
import time
from pathlib import Path

ROOT = Path(r"C:\Users\walim\RedSight")
OVERLAY = ROOT / "app" / "ui" / "action_palette_stage102.py"
LAUNCHER = ROOT / "launch_redsight_command_center.py"
COMMAND_CENTER = ROOT / "app" / "ui" / "command_center.py"
STAGE10 = ROOT / "app" / "ui" / "action_palette_stage10.py"
GATEWAY10 = ROOT / "redsight_actions" / "gateway_stage10.py"
ASSET_DIR = ROOT / "assets"
ICON = ASSET_DIR / "redsight.ico"

STAMP = time.strftime("%Y%m%d-%H%M%S")
BACKUP = ROOT / ".repair-backups" / ("stage102-ui-upgrade-" + STAMP)
BACKUP.mkdir(parents=True, exist_ok=True)

for required in (LAUNCHER, COMMAND_CENTER, STAGE10, GATEWAY10):
    if not required.exists():
        raise RuntimeError("Missing required Stage 10 component: " + str(required))

for path in (OVERLAY, LAUNCHER, ICON):
    if path.exists():
        shutil.copy2(path, BACKUP / (path.name + ".before"))

source = base64.b64decode("").decode("utf-8")
ast.parse(source, filename=str(OVERLAY))
OVERLAY.parent.mkdir(parents=True, exist_ok=True)
temp = OVERLAY.with_suffix(".py.stage102.tmp")
temp.write_text(source, encoding="utf-8")
os.replace(temp, OVERLAY)

launcher = LAUNCHER.read_text(encoding="utf-8-sig", errors="replace")

launcher = re.sub(
    r"(?m)^from app\.ui\.action_palette(?:_stage9|_stage91|_stage10|_stage101|_stage102)? "
    r"import install_action_hooks, attach_action_palette\s*$\n?",
    "",
    launcher,
)
launcher = re.sub(
    r"(?m)^\s*install_action_hooks\(CommandCenterMainWindow\)\s*$\n?",
    "",
    launcher,
)
launcher = re.sub(
    r"(?m)^\s*attach_action_palette\(.*?\)\s*$\n?",
    "",
    launcher,
)

launcher = re.sub(
    r"(?s)# REDSIGHT_STAGE102_HIDPI_BEGIN.*?# REDSIGHT_STAGE102_HIDPI_END\s*",
    "",
    launcher,
)
hidpi = (
    "# REDSIGHT_STAGE102_HIDPI_BEGIN\n"
    "import os as _redsight_os\n"
    "_redsight_os.environ.setdefault('QT_AUTO_SCREEN_SCALE_FACTOR', '1')\n"
    "_redsight_os.environ.setdefault('QT_SCALE_FACTOR_ROUNDING_POLICY', 'PassThrough')\n"
    "# REDSIGHT_STAGE102_HIDPI_END\n"
)
future = re.search(r"(?m)^from __future__ import .+$", launcher)
if future:
    launcher = launcher[:future.end()] + "\n" + hidpi + launcher[future.end():]
else:
    launcher = hidpi + launcher

if not re.search(r"(?m)^from pathlib import Path\s*$", launcher):
    future = re.search(r"(?m)^from __future__ import .+$", launcher)
    if future:
        launcher = launcher[:future.end()] + "\nfrom pathlib import Path" + launcher[future.end():]
    else:
        launcher = "from pathlib import Path\n" + launcher

command_import = re.search(
    r"(?m)^from app\.ui\.command_center import CommandCenterMainWindow\s*$",
    launcher,
)
if not command_import:
    raise RuntimeError("CommandCenterMainWindow import not found in launcher.")

integration = (
    "\nfrom app.ui.action_palette_stage102 "
    "import install_action_hooks, attach_action_palette\n"
    "install_action_hooks(CommandCenterMainWindow)"
)
launcher = launcher[:command_import.end()] + integration + launcher[command_import.end():]

window_match = re.search(
    r"(?m)^([ \t]*)window\s*=\s*CommandCenterMainWindow\(\)\s*$",
    launcher,
)
if not window_match:
    raise RuntimeError("CommandCenterMainWindow() construction not found in launcher.")

indent = window_match.group(1)
attach_line = indent + "attach_action_palette(window, Path(__file__).resolve().parent)"
launcher = launcher[:window_match.end()] + "\n" + attach_line + launcher[window_match.end():]

ast.parse(launcher, filename=str(LAUNCHER))
temp_launcher = LAUNCHER.with_suffix(".py.stage102.tmp")
temp_launcher.write_text(launcher, encoding="utf-8")
os.replace(temp_launcher, LAUNCHER)

ASSET_DIR.mkdir(parents=True, exist_ok=True)
try:
    from PIL import Image, ImageDraw

    size = 256
    image = Image.new("RGBA", (size, size), (7, 11, 16, 255))
    draw = ImageDraw.Draw(image)
    red = (245, 38, 48, 255)
    soft = (255, 90, 99, 255)
    cx = cy = size // 2

    draw.ellipse((34, 34, 222, 222), outline=red, width=14)
    draw.ellipse((78, 78, 178, 178), outline=soft, width=8)
    draw.ellipse((116, 116, 140, 140), fill=red)

    draw.line((cx, 8, cx, 91), fill=red, width=14)
    draw.line((cx, 165, cx, 248), fill=red, width=14)
    draw.line((8, cy, 91, cy), fill=red, width=14)
    draw.line((165, cy, 248, cy), fill=red, width=14)

    image.save(
        ICON,
        format="ICO",
        sizes=[(16,16),(24,24),(32,32),(48,48),(64,64),(128,128),(256,256)],
    )
except Exception as exc:
    raise RuntimeError("Could not create RedSight branded icon: " + repr(exc))

print("STAGE102_SOURCE_INSTALL=PASS")
print("OVERLAY=" + str(OVERLAY))
print("ICON=" + str(ICON))
print("BACKUP=" + str(BACKUP))
